import { styled, Text } from '@tamagui/web';
import type { ReactNode, Ref } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { cx, cxx } from '../../helpers/composeClassNames';
import type { PartAttributes } from '../../types/ElementAttributes';

export type ItemDescriptionProps = PartAttributes<HTMLElement> & {
	/**
	 * Places the description right after the title, as with a username after a name.
	 * In narrow lists it moves to its own line.
	 */
	inline?: boolean;
	children?: ReactNode;
};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

// Declared where it renders: zero-runtime only erases a `styled()` whose every use is in its own module
const ItemDescriptionFrame = styled(Text, {
	display: 'flex',
	wordWrap: 'inherit',
	render: 'div',
	position: 'static',
	flexDirection: 'row',
	flexShrink: 1,
	alignItems: 'normal',
	minWidth: 0,
	minHeight: 'auto',
	overflow: 'hidden',
	whiteSpace: 'nowrap',
	textOverflow: 'ellipsis',
	flexGrow: 1,
	flexBasis: 'auto',
	color: 'var(--rcx-item-color-font-secondary, var(--rcx-color-font-secondary-info, #6c737a))',
	fontSize: '0.75rem',
	fontWeight: 400,
	lineHeight: '1rem',
	letterSpacing: '0rem',
	variants: {
		inline: {
			true: {
				display: 'inline',
				marginInlineStart: '4px',
			},
			false: {
				display: 'block',
			},
		},
	},
});

// end of generated

/**
 * The secondary line of an `Item`, such as a last message preview or a username.
 */
const ItemDescription = (props: ItemDescriptionProps) => {
	const inline = !!props.inline;
	const className = cx(cxx('rcx-item__description')({ inline }), props.className);

	// One branch per tag: zero-runtime has to know it
	if (inline) {
		return (
			<ItemDescriptionFrame
				inline
				className={className}
				render={<span {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} />}
			>
				{props.children}
			</ItemDescriptionFrame>
		);
	}

	return (
		<ItemDescriptionFrame
			inline={false}
			className={className}
			render={<div {...ariaAndDataAttributes(props)} ref={props.ref as Ref<HTMLDivElement>} id={props.id} title={props.title} />}
		>
			{props.children}
		</ItemDescriptionFrame>
	);
};

export default ItemDescription;
